1140	  // 临时文件名携带进程号与随机标识：同进程多次保存互不覆盖，崩溃后的遗留文件
1141	  // 也能凭进程号确认持有者已退出后再清理，绝不清除存活请求的临时文件。
1142	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`);
1143	  // 仅供本地回归检查使用的崩溃注入点（未设置时完全无作用）：
1144	  //   before-tmp  原子替换前（尚未写临时文件）被 kill，遗留锁、业务不生效
1145	  //   after-tmp   临时文件写完、rename 之前被 kill，遗留锁与临时文件、业务不生效
1146	  //   after-rename 原子替换之后、输出成功之前被 kill，完整提交保留
1147	  const crashPoint = process.env.STOCKROOM_TEST_CRASH;
1148	  if (crashPoint === 'before-tmp') process.kill(process.pid, 'SIGKILL');
1149	  let fd: number;
1150	  try {
1151	    mkdirSync(dataDir, { recursive: true });
1152	    fd = openSync(tmp, 'wx'); // 原子创建：同名（极小概率）直接失败而不是覆盖他人内容
1153	    try {
1154	      writeFileSync(fd, JSON.stringify(store, null, 2) + '\n', 'utf8');
1155	      fsyncSync(fd); // 内容落盘后再 rename，保证替换后即完整提交
1156	    } finally {
1157	      closeSync(fd);
1158	    }
1159	    if (crashPoint === 'after-tmp') process.kill(process.pid, 'SIGKILL');
1160	    renameSync(tmp, path);
1161	    if (crashPoint === 'after-rename') process.kill(process.pid, 'SIGKILL');
1162	  } catch (e) {
1163	    try {
1164	      unlinkSync(tmp); // 写入失败不留下本请求的半成品临时文件
1165	    } catch {
1166	      /* 临时文件不存在也无妨 */
1167	    }
1168	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
1169	  }
1170	}
