1690	          }
1691	        }
1692	        // 仅供回归：接任锚点已建、闸门 rename 之前崩溃（取得写入机会前退出）。
1693	        if (process.env.STOCKROOM_TEST_CRASH === 'after-take-link') process.kill(process.pid, 'SIGKILL');
1694	        try {
1695	          renameSync(takePath, gatePath); // 覆盖旧死闸门：唯一协调者 + 死属主，单方向、无竞争空隙
