1734	function parseArgs(
1735	  tokens: string[],
1736	  singles: string[],
1737	  multis: string[] = [],
1738	): ParsedArgs {
1739	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
1740	  const singleSet = new Set(singles);
