 * 取得写入机会后清理异常退出写进程遗留的临时文件、孤立锁身份/接任锚点文件与
 * 各类回收物。只有文件名（或协调者内容）中 pid 已退出的才删除；并且**任何**与
 * 现存闸门同 inode 的文件都绝不删除——那一定是当前占用本身的硬链接（身份、
 * 接任锚点或协调者）。存活等待者的身份文件与现任协调者文件凭存活 pid 一律保留。
 */
function cleanStaleFiles(dir: string): void {
  let names: string[];
