    // 锚点原子 rename 覆盖到闸门名。身份文件原名保留，闸门全程存在。
    testSync('take-before');
    try {
      linkSync(idPath, takePath);
    } catch (e2) {
      if ((e2 as NodeJS.ErrnoException).code === 'EEXIST') {
        // 极小概率同名残留：仅当它已是本进程身份的硬链接时续用，否则报错让出。
        let same = false;
