          // 留下新死闸门 + 死协调者/身份/锚点，后续请求须自动再接任）。
          if (process.env.STOCKROOM_TEST_CRASH === 'after-take-rename') process.kill(process.pid, 'SIGKILL');
          // 末点复核（接任 rename 之后）：闸门必须已是本进程身份 inode，且协调者
