          let selfIno: number | bigint | undefined;
          try {
            selfIno = statSync(idPath).ino;
          } catch {
            selfIno = undefined;
          }
          const after = gateVerdict(dir);
          if (selfIno !== undefined && after.exists && after.ino === selfIno && coordStillMine()) {
            testSync('take-after');
            return finish(true); // 协调者身份随闸门持有到 release
          }
          testSync('take-recheck'); // rename 后发现资格不完整：交回占用/让贤，绝不进入业务
          if (selfIno !== undefined && after.exists && after.ino === selfIno) {
            // 闸门名在本进程 inode 上，但协调者名已易主。
            const cp = readCoordPid(coordPath);
            if (cp !== null && cp !== process.pid && pidAlive(cp)) {
              // 存活第三者持有有效协调资格：把闸门名无缝交还其 inode——
              // rename(其协调者硬链接 -> 闸门名)，闸门全程存在；第三者的身份
              // 文件仍锚定同一 inode。本请求让贤重轮，绝不开展业务。
              try {
                renameSync(coordPath, gatePath);
              } catch {
                /* 交还失败：第三者可能已自行让贤；保持现状交由下一轮裁决 */
              }
              standDown();
            } else {
              // 无存活第三者：本请求的身份硬链接已合法锚定闸门，收回死/缺的
              // 协调者名换成本请求后正常持有。
              if (reclaimDeadCoord()) {
                testSync('take-after');
                return finish(true);
              }
              standDown();
            }
          } else {
            // 闸门已不属本进程（被合法持有者占据）：让贤重轮，绝不触碰闸门。
            standDown();
          }
        }
      }
      if (amCoordinator) {
        // 自己是协调者但闸门已被合法存活持有者占据（接任前状态变化）：让贤。
